-- Reviewed botanical content. Source URLs and taxon decisions are recorded in the paired sources document.
-- Fill only blank passport topics on the exact published plant card; preserve owner edits.
CREATE TEMP TABLE reviewed_plant_passports (
 product_code bigint PRIMARY KEY, expected_name text NOT NULL, passport jsonb NOT NULL
) ON COMMIT DROP;
INSERT INTO reviewed_plant_passports VALUES
 (40,'Араукария','{"humidity":"Араукарии подходит обычная или умеренно повышенная влажность воздуха. Не ставьте горшок вплотную к горячей батарее; при сухом воздухе полезно увлажнять воздух вокруг растения.","temperature":"Держите араукарию в светлом месте без мороза и холодных сквозняков. Летом можно вынести её в защищённое место, а до похолодания вернуть в помещение.","soil":"Нужен рыхлый, хорошо дренируемый грунт для горшечных деревьев с минеральным разрыхлителем. В горшке обязательны дренажные отверстия.","fertilizer":"С марта по сентябрь подкармливайте сбалансированным удобрением по инструкции; зимой, когда рост замедлен, подкормки прекратите.","growthRate":"Араукария постепенно наращивает центральный побег и новые ярусы ветвей. В горшке её рост зависит от света, объёма корней и сезонных условий."}'::jsonb),
 (853,'Араукария 20 см D10','{"humidity":"Араукарии подходит обычная или умеренно повышенная влажность воздуха. Не ставьте горшок вплотную к горячей батарее; при сухом воздухе полезно увлажнять воздух вокруг растения.","temperature":"Держите араукарию в светлом месте без мороза и холодных сквозняков. Летом можно вынести её в защищённое место, а до похолодания вернуть в помещение.","soil":"Нужен рыхлый, хорошо дренируемый грунт для горшечных деревьев с минеральным разрыхлителем. В горшке обязательны дренажные отверстия.","fertilizer":"С марта по сентябрь подкармливайте сбалансированным удобрением по инструкции; зимой, когда рост замедлен, подкормки прекратите.","growthRate":"Араукария постепенно наращивает центральный побег и новые ярусы ветвей. В горшке её рост зависит от света, объёма корней и сезонных условий."}'::jsonb),
